const VIDEO_CATALOG = Object.fromEntries(Object.entries(VIDEO_LESSONS).map(([topic,ids])=>[topic,ids.map(id=>({id,...VIDEO_RECORDS[id]}))]));
const VIDEO_NOTES = {"p5-3":"Aulas de base da Lei Orgânica Nacional do MP. Para a LC estadual 13/1991 e suas alterações, complemente com a legislação oficial do MP-MA; estes vídeos não são aulas específicas dessa lei estadual.","p5-4":"Aulas de base sobre o Ministério Público e sua organização nacional. A estrutura específica do MP-MA deve ser conferida nas normas institucionais.","p5-12":"Aulas sobre como estudar legislação. As normas de um edital futuro só poderão ser selecionadas quando ele for publicado.","t23":"Aulas de base sobre a organização do MP e estudo de legislação. Confira a LC 13/1991 e as normas vigentes diretamente no portal do MP-MA.","t91":"Aulas de método para estudar legislação. O conjunto de normas adicionais dependerá do edital."};
